{"command": "python3 <<'PY' 2>&1 | head -n 3000
import pty, os, subprocess, sys, time, fcntl

def repl_session(commands, wait=0.5):
    master, slave = pty.openpty()
    p = subprocess.Popen(['./executable','-r'], stdin=slave, stdout=slave, stderr=slave)
    os.close(slave)
    flags = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    time.sleep(wait)
    def drain():
        out=b""
        try:
            while True:
                d=os.read(master, 8192)
                if not d: break
                out+=d
        except: pass
        return out
    init = drain()
    print("INIT:", repr(init))
    for cmd in commands:
        os.write(master, cmd+b"\n")
        time.sleep(wait)
        print(f"CMD {repr(cmd)} => {repr(drain())}")
    try:
        p.wait(timeout=2)
        print("exited", p.returncode)
    except:
        try: p.terminate(); p.wait(timeout=2)
        except: 
            try: p.kill()
            except: pass
        print("killed rc", p.returncode)
    # drain remaining
    try:
        print("FINAL:", repr(drain()))
    except Exception as e:
        print(e)

# test various repl commands
repl_session([b'"hi";', b':s', b':u', b':s', b':r', b':s', b':c', b':s', b'bad input', b':e'])
PY
"}

