struct Ctx {
    chars: Vec<char>,
    pos: usize,
    vars: HashMap<String, String>,
}
impl Ctx {
    fn new(s: &str) -> Self { Self { chars: s.chars().collect(), pos: 0, vars: HashMap::new() } }
    fn lc(&self, p: usize) -> (usize, usize, String) {
        let q = p.min(self.chars.len());
        let mut line=1usize; let mut ls=0usize;
        for i in 0..q { if self.chars[i]=='\n' { line+=1; ls=i+1; } }
        let mut le=self.chars.len();
        for i in q..self.chars.len() { if self.chars[i]=='\n' { le=i; break; } }
        let t: String=self.chars[ls..le].iter().collect();
        (line, q-ls+1, t)
    }
    fn perr(&self, p: usize, e: Vec<String>) -> CE {
        let (l,c,t)=self.lc(p); CE::Parse{line:l,col:c,text:t,exp:e}
    }
    fn skw(&mut self) {
        loop {
            if self.pos>=self.chars.len(){break;}
            let c=self.chars[self.pos];
            if c==' '||c=='\t'||c=='\r'||c=='\n'{self.pos+=1;continue;}
            if c=='/'&&self.pos+1<self.chars.len()&&self.chars[self.pos+1]=='*'{
                let mut j=self.pos+2; let mut f=false;
                while j+1<self.chars.len(){ if self.chars[j]=='*'&&self.chars[j+1]=='/'{f=true;j+=2;break;} j+=1; }
                if f{self.pos=j;continue;}else{break;}
            }
            break;
        }
    }
    fn atls(&self, p: usize)->bool{
        let q=p.min(self.chars.len());
        let mut last=None;
        for i in 0..q{ if self.chars[i]=='\n'{last=Some(i);} }
        let s=last.map(|x|x+1).unwrap_or(0);
        for i in s..q{ if self.chars[i]!=' '&&self.chars[i]!='\t'{return false;}}
        true
    }
    fn sktr(&mut self){
        loop{
            self.skw();
            if self.pos+1<self.chars.len()&&self.chars[self.pos]=='/'&&self.chars[self.pos+1]=='/'{
                if self.atls(self.pos){
                    while self.pos<self.chars.len()&&self.chars[self.pos]!='\n'{self.pos+=1;}
                    continue;
                }
            }
            break;
        }
    }
    fn lit(&mut self,s:&str)->bool{
        let v:Vec<char>=s.chars().collect();
        if self.pos+v.len()<=self.chars.len()&&self.chars[self.pos..self.pos+v.len()]==v[..]{self.pos+=v.len();true}else{false}
    }
}
