    fn perr(&self, p: usize, e: Vec<String>) -> CE {
        let (l,c,t)=self.lc(p); CE::Parse{line:l,col:c,text:t,exp:e}
    }
    fn skw(&mut self) {
        loop {
            if self.pos>=self.chars.len(){break;}
            let c=self.chars[self.pos];
            if c==' '||c=='\t'||c=='\r'||c=='\n'{self.pos+=1;continue;}
            if c=='/'&&self.pos+1<self.chars.len()&&self.chars[self.pos+1]=='*'{
                let mut j=self.pos+2; let mut f=false;
                while j+1<self.chars.len(){ if self.chars[j]=='*'&&self.chars[j+1]=='/'{f=true;j+=2;break;} j+=1; }
                if f{self.pos=j;continue;}else{break;}
            }
            break;
        }
    }
    fn atls(&self, p: usize)->bool{
        let q=p.min(self.chars.len());
        let mut last=None;
        for i in 0..q{ if self.chars[i]=='\n'{last=Some(i);} }
        let s=last.map(|x|x+1).unwrap_or(0);
        for i in s..q{ if self.chars[i]!=' '&&self.chars[i]!='\t'{return false;}}
