fn esc_needed(c:char)->bool{matches!(c,'$'|'('|')'|'*'|'+'|'.'|'?'|'['|']'|'^'|'{'|'|'|'}')}
fn esc_l(c:char)->String{if esc_needed(c){format!("\\{}",c)}else{c.to_string()}}
