    fn p_var_inv(&mut self) -> Result<Option<String>, CE> {
        let sv = self.pos;
        self.skw();
        if self.pos >= self.chars.len() || self.chars[self.pos] != '.' { self.pos = sv; return Ok(None); }
        self.pos += 1;
        if self.pos >= self.chars.len() {
            return Err(self.perr(self.pos, vec![ss("identifier")]));
        }
        let c = self.chars[self.pos];
        if !(c.is_ascii_alphabetic() || c == '_') {
            return Err(self.perr(self.pos, vec![ss("identifier")]));
        }
        let mut j = self.pos + 1;
        while j < self.chars.len() {
            let d = self.chars[j];
            if d.is_ascii_alphabetic() || d == '_' || d == ' ' { j += 1; } else { break; }
        }
        let raw: String = self.chars[self.pos..j].iter().collect();
        let name = raw.trim().to_string();
        // check for digits after? e.g., ".foo1" where after "foo" next is '1' (digit). Original for ".foo1;" gives root error at 1:1, not identifier. Good. Our parsing: raw="foo" (up to '1'), then pos at j (at '1'), then skip ws (0), then expect ';' but gets '1', so fails (return None, then top-level root). Good. So need to handle: after name, skip ws, expect ';', else return None.
        self.pos = j;
        self.skw();
        if self.pos < self.chars.len() && self.chars[self.pos] == ';' {
            self.pos += 1;
            if let Some(v) = self.vars.get(&name) {
