impl Ctx {
    fn p_not_full(&mut self) -> Result<Option<String>, CE> {
        let sv = self.pos;
        self.skw();
        if self.pos + 2 >= self.chars.len() { self.pos = sv; return Ok(None); }
        if self.chars[self.pos] != 'n' { self.pos = sv; return Ok(None); }
        if self.chars[self.pos+1] != 'o' { self.pos = sv; return Ok(None); }
        if self.chars[self.pos+2] != 't' { self.pos = sv; return Ok(None); }
        self.pos += 3;
        self.skw();
        if self.pos >= self.chars.len() {
            return Err(self.perr(self.pos, vec![ss("amount"), ss("class_content"), ss("ascii_range_start"), ss("assertion_type")]));
        }
        // try ahead/behind with block (negated lookaround)
        let s1 = self.pos;
        if self.pos + 4 < self.chars.len() {
            let mut is_ahead = false;
            let mut is_behind = false;
            if self.chars[self.pos]=='a' && self.chars[self.pos+1]=='h' && self.chars[self.pos+2]=='e' && self.chars[self.pos+3]=='a' && self.chars[self.pos+4]=='d' {
                is_ahead = true;
            }
            if self.pos + 5 < self.chars.len() && self.chars[self.pos]=='b' && self.chars[self.pos+1]=='e' && self.chars[self.pos+2]=='h' && self.chars[self.pos+3]=='i' && self.chars[self.pos+4]=='n' && self.chars[self.pos+5]=='d' {
                is_behind = true;
            }
            if is_ahead || is_behind {
                let adv = if is_ahead {5} else {6};
