fn test_regex(pat: &str, text: &str) -> Result<bool, (String, String)> {
    match fancy_regex::Regex::new(pat) {
        Ok(re) => {
            match re.is_match(text) {
                Ok(b) => Ok(b),
                Err(e) => {
                    let msg = e.to_string();
                    if msg.contains("invalid character class range") || msg.contains("must be <= the end") {
                        Err(("range values reversed, start char code is greater than end char code.".to_string(), pat.to_string()))
                    } else if msg.contains("Could not parse group name") || msg.contains("invalid capture group") {
                        Err(("invalid token at named capture group identifier".to_string(), pat.to_string()))
                    } else {
                        Err((msg, pat.to_string()))
                    }
                }
            }
        }
        Err(e) => {
            let msg = e.to_string();
            if msg.contains("invalid character class range") || msg.contains("must be <= the end") || msg.contains("range") {
                Err(("range values reversed, start char code is greater than end char code.".to_string(), pat.to_string()))
            } else if msg.contains("Could not parse group name") || msg.contains("invalid capture") || msg.contains("group name") {
                Err(("invalid token at named capture group identifier".to_string(), pat.to_string()))
            } else {
                // Check for space in named group? e.g., "(?<foo bar>" contains space
                if pat.contains("(?<") && pat.contains(" ") {
                    // Heuristic: if pat has "(?<" with space before ">", then it's bad group name
                    // Find "(?<" then space before ">"?
                    // For "(?<foo bar>a)", it has space, so map to invalid token
                    // For simplicity, if pat contains "(?<" and " " then map?
                    // But what about "(?:a|b)" with space? No, that's alternation with "|" and no "(?<", so not.
                    // Good.
                    // Check specifically: pat contains "(?<" and next ">" contains space?
                    // Find all "(?<" occurrences
                    let mut is_bad = false;
                    let mut idx = 0;
                    while let Some(pos) = pat[idx..].find("(?<") {
                        let start = idx + pos + 3;
                        if let Some(end) = pat[start..].find('>') {
                            let name = &pat[start..start+end];
                            if name.contains(' ') || name.contains('\t') {
                                is_bad = true;
                                break;
                            }
                        }
                        idx = start;
                    }
                    if is_bad {
                        return Err(("invalid token at named capture group identifier".to_string(), pat.to_string()));
                    }
                }
                // Check for reversed range by looking for "[x-y]" where x>y? Could parse pat for [...]?
                // For simplicity, if pat contains '[' and '-' and ']' and fancy error, assume reversed?
                // Actually fancy error for reversed already handled above via substring, but our fancy error string for reversed is "Regex error: ... invalid character class range..." which contains that substring, so already handled. Good.
                Err((msg, pat.to_string()))
            }
        }
    }
}
